changeSet.sql:
ALTER TABLE global_users ALTER COLUMN password_hash DROP NOT NULL;

ALTER TABLE global_users ADD COLUMN IF NOT EXISTS auth_provider VARCHAR(32) NOT NULL DEFAULT 'LOCAL';
ALTER TABLE global_users ADD COLUMN IF NOT EXISTS provider_subject_id VARCHAR(255);
ALTER TABLE global_users ADD COLUMN IF NOT EXISTS avatar_url VARCHAR(1024);

CREATE UNIQUE INDEX IF NOT EXISTS uq_global_users_provider 
ON global_users (auth_provider, provider_subject_id) 
WHERE provider_subject_id IS NOT NULL;
